use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let digits: Vec<char> = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 3 {
            continue
        }
        let from: int = parts[1].parse::<int>().unwrap_or(10)
        let to: int = parts[2].parse::<int>().unwrap_or(10)
        let mut n: int = 0
        for ch in parts[0].chars() {
            let mut d: int = 0
            for j in 0..36 {
                if digits[j] == ch.to_ascii_uppercase() {
                    d = j
                }
            }
            n = n * from + d
        }
        if n == 0 {
            println("0")
            continue
        }
        let mut out: Vec<string> = []
        while n > 0 {
            let r: int = n % to
            out.push("${digits[r]}")
            n = n / to
        }
        out.reverse()
        println(out.join(""))
    }
}

